private val payments = CircuitBreaker.of("payments", CircuitBreakerConfig.custom()
    .failureRateThreshold(50f)
    .minimumNumberOfCalls(20)
    .waitDurationInOpenState(Duration.ofSeconds(15))
    .permittedNumberOfCallsInHalfOpenState(3)
    .build())

suspend fun authorize(order: Order): Receipt =
    payments.executeSuspendFunction { api.authorize(order) }
